/*
 * Worker / backend parity (T7.7): the browser math (used by the worker and its main-thread fallback)
 * reproduces science/marswalk/eva_model.py within 1e-6 relative on fixtures generated by the backend.
 */
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import { evaluateProfile } from "../src/marswalk/marswalkMath.js";
import { runOnMainThread } from "../src/perf/workerClient.js";

const fixture = JSON.parse(readFileSync(new URL("./fixtures/eva_parity.json", import.meta.url), "utf8"));
const close = (a, b, tol) => Math.abs(a - b) <= tol * Math.max(1, Math.abs(b));

for (const c of fixture.cases) {
  test(`parity: ${c.name}`, () => {
    const rough = c.rough.map((x) => (x === null ? NaN : x));
    const ds = Float64Array.from(c.ds);
    const dz = Float64Array.from(c.dz);
    const r = evaluateProfile(ds, dz, rough, c.v);
    const tol = fixture.tolerance_rel;
    assert.ok(close(r.outbound_h, c.expected.outbound_h, tol), `outbound ${r.outbound_h} vs ${c.expected.outbound_h}`);
    assert.ok(close(r.return_h, c.expected.return_h, tol), `return ${r.return_h} vs ${c.expected.return_h}`);
    assert.equal(r.turnaround.index, c.expected.pnr_index);
    assert.equal(r.turnaround.reached_target, c.expected.reached_target);
    assert.ok(close(r.turnaround.distance_m, c.expected.pnr_distance_m, tol));
    assert.ok(close(r.round_trip.metabolic_kcal_est.value, c.expected.kcal_round_trip, tol));
    assert.ok(close(r.outbound.o2_kg_est.value, c.expected.o2_kg_outbound, tol));
    // The worker fallback path runs the very same function.
    const fallback = runOnMainThread("evaluate", { ds, dz, rough, v: c.v });
    assert.deepEqual(fallback, r);
  });
}
